import openpyxl
wb=openpyxl.load_workbook('/root/output/result.xlsx')
ws=wb['Data']
# Search for year values 2019-2023 in Data
years=set([2019,2020,2021,2022,2023])
found=[]
for row in range(1, ws.max_row+1):
    for col in range(1, ws.max_column+1):
        v=ws.cell(row=row,column=col).value
        if v in years:
            found.append((ws.cell(row=row,column=col).coordinate, v))
print('Year cells found:', found)

# Print top 30 rows for columns A-L but only non-empty cells
for r in range(1,31):
    non=[]
    for c in range(1,13):
        v=ws.cell(row=r,column=c).value
        if v not in (None,''):
            non.append((openpyxl.utils.get_column_letter(c)+str(r), v))
    if non:
        print('Row', r, non)
